"""Class 5 Writing & Grammar sets 6-10 (original)."""
from eng9_lib import Q, OR
def N(q, a): return Q(q, a, "3")
def L(q, a): return Q(q, a, "5")
def A(q, a): return Q(q, a, "4")
def g(q, a): return Q(q, a, "1")
SETS = {}

